packages/files/extension.json.content:
{
  "protocol": 3,
  "id": "files",
  "title": "Файлы",
  "description": "Панель проекта в духе Zed: дерево рабочей папки с цветами git, создание, переименование и удаление файлов.",
  "icon": "folder-tree",
  "command": [
    "bin/files"
  ],
  "surfaces": {
    "panel": {
      "title": "Файлы"
    },
    "document": {
      "label": "{filename}"
    }
  },
  "required_features": [
    "widgets.controls.v1"
  ],
  "author": "Proteus Project"
}

packages/git/extension.json.content:
{
  "protocol": 3,
  "id": "git",
  "title": "Git",
  "description": "Панель git как в Zed: индекс, коммит, отмена изменений, ветки и история.",
  "icon": "git-branch",
  "command": [
    "bin/git"
  ],
  "surfaces": {
    "panel": {
      "title": "Git"
    },
    "document": {
      "label": "{filename}"
    },
    "badge": {
      "place": "composer_end"
    },
    "popup": {
      "width": 300
    }
  },
  "required_features": [
    "widgets.controls.v1",
    "widgets.diff.v1",
    "widgets.lanes.v2",
    "widgets.disclosure.v1",
    "widgets.person.v1",
    "documents.title.v1",
    "widgets.picker.v1",
    "widgets.status.v1",
    "widgets.selection.v1",
    "widgets.search.v1"
  ],
  "author": "Proteus Project"
}

